get_info_schema:
{
    "name": "get_info",
    "description": "Returns information about a symbol.",
    "parameters": {
        "type": "object",
        "properties": {
            "name": {
                "type": "string",
                "description": "class, function or method name, as in 'f' for function f or 'C.foo' for method foo in class C."
            }
        },
        "required": ["name"]
    }
}
